import { describe, it, expect } from "vitest";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";

describe("enforceInReviewRequiresPrUrl", () => {
  it("passes through in_review with a valid pr_url", () => {
    const input: ExecutorResult = {
      terminal_status: "in_review",
      pr_url: "https://github.com/owner/repo/pull/42",
    };
    const { result, rewritten } = enforceInReviewRequiresPrUrl(input);
    expect(rewritten).toBe(false);
    expect(result).toBe(input);
  });

  it("rewrites in_review without pr_url to blocked", () => {
    const input: ExecutorResult = {
      terminal_status: "in_review",
    };
    const { result, rewritten } = enforceInReviewRequiresPrUrl(input);
    expect(rewritten).toBe(true);
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("pr_url_missing");
