/**
 * RAG audit — extract tool_use / tool_result pairs for mcp__rag-server__rag_query
 * from claude --output-format stream-json stdout.
 */

export interface RagQueryEvent {
  query: string;
  chunks_returned: number;
  top_score: number | null;
  scores: number[];
}

interface RagChunk {
  score?: unknown;
}

/**
 * Scan stream-json stdout and correlate rag_query tool_use events with their
 * matching tool_result responses.
 *
 * Returns one RagQueryEvent per completed RAG call (unmatched tool_use records
 * with no corresponding tool_result are dropped).
 */
export function extractRagQueries(stdout: string): RagQueryEvent[] {
  // Map from tool_use_id → query text (collected from assistant events).
  const pending = new Map<string, string>();
  const results: RagQueryEvent[] = [];

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;

    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    // assistant events contain tool_use blocks in message.content.
    if (parsed.type === "assistant") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content as unknown[]) {
        if (!block || typeof block !== "object") continue;
        const b = block as Record<string, unknown>;
        if (
          b.type === "tool_use" &&
          b.name === "mcp__rag-server__rag_query" &&
          typeof b.id === "string"
        ) {
          const input = b.input as Record<string, unknown> | undefined;
          const query = typeof input?.query === "string" ? input.query : "";
          pending.set(b.id, query);
        }
      }
      continue;
    }

    // user events contain tool_result blocks in message.content.
    if (parsed.type === "user") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content as unknown[]) {
        if (!block || typeof block !== "object") continue;
        const b = block as Record<string, unknown>;
        if (b.type !== "tool_result" || typeof b.tool_use_id !== "string") continue;

        const query = pending.get(b.tool_use_id);
        if (query === undefined) continue; // not a RAG call

        pending.delete(b.tool_use_id);

        // Parse the tool result content.
        const scores = parseScores(b.content);
        results.push({
          query,
          chunks_returned: scores.length,
          top_score: scores.length > 0 ? Math.max(...scores) : null,
          scores,
        });
      }
    }
  }

  return results;
}

function parseScores(content: unknown): number[] {
  // Tool result content may be a string (JSON-encoded array) or an array of
  // content blocks where text blocks carry the JSON-encoded result.
  let raw: string | undefined;

  if (typeof content === "string") {
    raw = content;
  } else if (Array.isArray(content)) {
    for (const block of content as unknown[]) {
      if (block && typeof block === "object") {
        const b = block as Record<string, unknown>;
        if (b.type === "text" && typeof b.text === "string") {
          raw = b.text;
          break;
        }
      }
    }
  }

  if (!raw) return [];

  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    const scores: number[] = [];
    for (const item of parsed as unknown[]) {
      if (item && typeof item === "object") {
        const chunk = item as RagChunk;
        if (typeof chunk.score === "number") {
          scores.push(chunk.score);
        }
      }
    }
    return scores;
  } catch {
    return [];
  }
}

