import { describe, it, expect } from "vitest";
import { extractTokenUsage } from "./token-usage.js";

function makeAssistantLine(input: number, output: number, model?: string): string {
  const msg: Record<string, unknown> = {
    usage: { input_tokens: input, output_tokens: output },
  };
  if (model) msg.model = model;
  return JSON.stringify({ type: "assistant", message: msg });
}

describe("extractTokenUsage", () => {
  it("returns undefined when stdout has no usage lines", () => {
    expect(extractTokenUsage("")).toBeUndefined();
    expect(extractTokenUsage("plain text\nno json here")).toBeUndefined();
  });

  it("sums tokens across multiple assistant turns", () => {
    const stdout = [
      makeAssistantLine(100, 50, "claude-sonnet-4-6"),
      makeAssistantLine(200, 80, "claude-sonnet-4-6"),
    ].join("\n");
    const result = extractTokenUsage(stdout);
    expect(result).toBeDefined();
    expect(result!.input).toBe(300);
    expect(result!.output).toBe(130);
  });

  it("extracts model from the last assistant event", () => {
    const stdout = [
      makeAssistantLine(100, 50, "claude-sonnet-4-6"),
      makeAssistantLine(200, 80, "claude-opus-4-7"),
    ].join("\n");
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-opus-4-7");
  });

  it("computes cost_usd correctly for claude-sonnet-4-6", () => {
    // 1M input @ $3/MTok + 1M output @ $15/MTok = $18
    const stdout = makeAssistantLine(1_000_000, 1_000_000, "claude-sonnet-4-6");
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-sonnet-4-6");
    expect(result!.cost_usd).toBeCloseTo(18.0, 6);
    expect(result!.pricingFallback).toBe(false);
  });

  it("computes cost_usd correctly for claude-opus-4-7", () => {
    // 1M input @ $15/MTok + 1M output @ $75/MTok = $90
    const stdout = makeAssistantLine(1_000_000, 1_000_000, "claude-opus-4-7");
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-opus-4-7");
    expect(result!.cost_usd).toBeCloseTo(90.0, 6);
    expect(result!.pricingFallback).toBe(false);
  });

  it("computes cost_usd correctly for claude-haiku-4-5-20251001", () => {
    // 1M input @ $0.8/MTok + 1M output @ $4/MTok = $4.8
    const stdout = makeAssistantLine(1_000_000, 1_000_000, "claude-haiku-4-5-20251001");
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-haiku-4-5-20251001");
    expect(result!.cost_usd).toBeCloseTo(4.8, 6);
    expect(result!.pricingFallback).toBe(false);
  });

  it("falls back to Sonnet rates for unknown models and sets pricingFallback=true", () => {
    // Unknown model — should use Sonnet rates (3/MTok input, 15/MTok output)
    const stdout = makeAssistantLine(1_000_000, 1_000_000, "claude-unknown-model-99");
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-unknown-model-99");
    expect(result!.pricingFallback).toBe(true);
    // cost_usd should equal Sonnet rates: $3 + $15 = $18
    expect(result!.cost_usd).toBeCloseTo(18.0, 6);
  });

  it("falls back to Sonnet model and rates when no model is in stream", () => {
    const stdout = makeAssistantLine(1_000_000, 1_000_000);
    const result = extractTokenUsage(stdout);
    expect(result!.model).toBe("claude-sonnet-4-6");
    expect(result!.pricingFallback).toBe(false);
  });

  it("handles legacy flat usage shape (no model extraction)", () => {
    const stdout = JSON.stringify({ usage: { input_tokens: 50, output_tokens: 20 } });
    const result = extractTokenUsage(stdout);
    expect(result!.input).toBe(50);
    expect(result!.output).toBe(20);
    expect(result!.model).toBe("claude-sonnet-4-6");
  });

  it("skips non-JSON lines without crashing", () => {
    const stdout = [
      "some plain text",
      makeAssistantLine(10, 5, "claude-sonnet-4-6"),
      "not json at all",
    ].join("\n");
    const result = extractTokenUsage(stdout);
    expect(result!.input).toBe(10);
  });

  it("cost_usd rounds correctly for small token counts", () => {
    // 1000 input + 500 output with sonnet rates
    // = (0.001 * 3) + (0.0005 * 15) = 0.003 + 0.0075 = 0.0105
    const stdout = makeAssistantLine(1000, 500, "claude-sonnet-4-6");
    const result = extractTokenUsage(stdout);
    expect(result!.cost_usd).toBeCloseTo(0.0105, 6);
  });
});
