    expect(r!.cost_usd).toBeCloseTo(18.0, 6);
    expect(r!.pricingFallback).toBe(false);
  });

  it("computes cost_usd for claude-opus-4-7", () => {
    const r = extractTokenUsage(mkLine(1_000_000, 1_000_000, "claude-opus-4-7"));
    expect(r!.cost_usd).toBeCloseTo(90.0, 6);
