/**
 * RAG audit — extract tool_use / tool_result pairs for mcp__rag-server__rag_query.
 */

export interface RagQueryEvent {
  query: string;
  chunks_returned: number;
  top_score: number | null;
  scores: number[];
}

export function extractRagQueries(stdout: string): RagQueryEvent[] {
  const pending = new Map<string, string>();
  const results: RagQueryEvent[] = [];

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;

    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    if (parsed.type === "assistant") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content as unknown[]) {
        if (!block || typeof block !== "object") continue;
        const b = block as Record<string, unknown>;
        if (b.type === "tool_use" && b.name === "mcp__rag-server__rag_query" && typeof b.id === "string") {
          const input = b.input as Record<string, unknown> | undefined;
          pending.set(b.id, typeof input?.query === "string" ? input.query : "");
        }
      }
      continue;
    }

    if (parsed.type === "user") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content as unknown[]) {
        if (!block || typeof block !== "object") continue;
        const b = block as Record<string, unknown>;
        if (b.type !== "tool_result" || typeof b.tool_use_id !== "string") continue;
        const query = pending.get(b.tool_use_id);
        if (query === undefined) continue;
        pending.delete(b.tool_use_id);
        const scores = parseScores(b.content);
        results.push({ query, chunks_returned: scores.length, top_score: scores.length > 0 ? Math.max(...scores) : null, scores });
      }
    }
  }

  return results;
}

function parseScores(content: unknown): number[] {
  let raw: string | undefined;
  if (typeof content === "string") {
    raw = content;
  } else if (Array.isArray(content)) {
    for (const block of content as unknown[]) {
      if (block && typeof block === "object") {
        const b = block as Record<string, unknown>;
        if (b.type === "text" && typeof b.text === "string") { raw = b.text; break; }
      }
    }
  }
  if (!raw) return [];
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return (parsed as unknown[])
      .filter(i => i && typeof i === "object" && typeof (i as Record<string,unknown>).score === "number")
      .map(i => (i as Record<string,unknown>).score as number);
  } catch { return []; }
}
