  1	/**
  2	 * Claude executor entrypoint — ABI-conformant.
  3	 *
  4	 * Reads ExecutorInput from environment variables, materializes the
  5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
  6	 * to result.json at RESULT_PATH.
  7	 *
  8	 * Formal ABI env vars (from ExecutorInput):
  9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
 10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
 11	 *   BRIEFING_PATH, RESULT_PATH
 12	 *   BUDGET_TOKENS (optional)
 13	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 14	 *
 15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
 16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
 17	 *   TASK_BRANCH        — management repo feature branch for git commits
 18	 *   GIT_AUTHOR_EMAIL   — for commit identity
 19	 *   GIT_AUTHOR_NAME    — for commit identity
 20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
 21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
 22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
 23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
 24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
 25	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
 26	 */
 27	
 28	import { spawn, execSync } from "node:child_process";
 29	import {
 30	  mkdirSync,
 31	  appendFileSync,
 32	  readFileSync,
 33	  writeFileSync,
 34	  existsSync,
 35	  readdirSync,
 36	  rmSync,
 37	  copyFileSync,
 38	  lstatSync,
 39	} from "node:fs";
 40	import { join, dirname } from "node:path";
 41	import { homedir } from "node:os";
 42	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
 43	import type { ExecutorResult } from "@workflow/runtime-abi";
 44	import { isValidResult } from "@workflow/runtime-abi";
 45	import { extractTokenUsage } from "./token-usage.js";
 46	import { enforceInReviewRequiresPrUrl } from "./enforce-pr-url.js";
 47	import { runRecovery, type SpawnResult } from "./recovery.js";
 48	import { resolveSSHKey } from "./resolve-ssh-key.js";
 49	import { redactSecrets } from "./redact-secrets.js";
 50	import { buildGitEnv } from "./git-env.js";
 51	
 52	// ── Helpers ───────────────────────────────────────────────────────────────────
 53	
 54	function requireEnv(name: string): string {
 55	  const val = process.env[name];
 56	  if (!val) throw new Error(`Required env var ${name} is not set`);
 57	  return val;
 58	}
 59	
 60	function emit(event: Record<string, unknown>): void {
 61	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
 62	}
 63	
 64	/**
 65	 * Materialize the implementation repo at taskRepoPath:
 66	 *   - If path exists and origin matches URL: fetch + checkout + pull
 67	 *   - Otherwise: clone fresh
 68	 */
 69	function materializeRepo(
 70	  taskRepoUrl: string,
 71	  taskRepoBranch: string,
 72	  taskRepoPath: string,
 73	  sshKeyPath: string | undefined,
 74	): void {
 75	  const env = buildGitEnv(sshKeyPath);
 76	  const opts = { env, stdio: "pipe" as const };
 77	
 78	  if (existsSync(join(taskRepoPath, ".git"))) {
 79	    let originUrl = "";
 80	    try {
 81	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
 82	        ...opts, encoding: "utf-8",
 83	      }).trim();
 84	    } catch { /* no remote — fall through to clone */ }
 85	
 86	    if (originUrl === taskRepoUrl) {
 87	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
 88	      // Discard local changes from a previous session before checkout.
 89	      try { execSync(`git -C "${taskRepoPath}" checkout -- .`, opts); } catch { /* ignore */ }
 90	      try {
 91	        execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
 92	      } catch {
 93	        execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
 94	      }
 95	      try {
 96	        execSync(
 97	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
 98	          opts,
 99	        );
100	      } catch {
101	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
102	      }
103	      return;
104	    }
105	  }
106	
107	  // Clone fresh.
108	  mkdirSync(dirname(taskRepoPath), { recursive: true });
109	  if (existsSync(taskRepoPath)) {
110	    rmSync(taskRepoPath, { recursive: true, force: true });
111	  }
112	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
113	  try {
114	    execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
115	  } catch {
116	    execSync(`git -C "${taskRepoPath}" checkout -b "${taskRepoBranch}"`, opts);
117	  }
118	}
119	
120	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
121	  { file: "yarn.lock",        tool: "yarn"    },
122	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
123	  { file: "bun.lockb",        tool: "bun"     },
124	  { file: "go.mod",           tool: "go"      },
125	  { file: "requirements.txt", tool: "python3" },
126	  { file: "pyproject.toml",   tool: "python3" },
127	  { file: "Cargo.toml",       tool: "cargo"   },
128	];
129	
130	function checkRequiredTools(taskRepoPath: string): string[] {
131	  const missing: string[] = [];
132	  const checked = new Set<string>();
133	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
134	    if (checked.has(tool)) continue;
135	    if (!existsSync(join(taskRepoPath, file))) continue;
136	    checked.add(tool);
137	    try {
138	      execSync(`which ${tool}`, { stdio: "pipe" });
139	    } catch {
140	      missing.push(tool);
141	    }
142	  }
143	  return missing;
144	}
145	
146	function copyWorkspaceClaude(workspaceRoot: string): void {
147	  const src = join(workspaceRoot, "CLAUDE.md");
148	  if (!existsSync(src)) return;
149	  const destDir = join(homedir(), ".claude");
150	  mkdirSync(destDir, { recursive: true });
151	  copyFileSync(src, join(destDir, "CLAUDE.md"));
152	}
153	
154	function copyDirRecursive(src: string, dest: string): void {
155	  mkdirSync(dest, { recursive: true });
156	  for (const entry of readdirSync(src)) {
157	    const srcPath = join(src, entry);
158	    const destPath = join(dest, entry);
159	    const stat = lstatSync(srcPath);
160	    if (stat.isDirectory()) {
161	      copyDirRecursive(srcPath, destPath);
162	    } else if (stat.isFile()) {
163	      copyFileSync(srcPath, destPath);
164	    }
165	  }
166	}
167	
168	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
169	  const globalSkillsDir = join(homedir(), ".claude", "skills");
170	  if (existsSync(globalSkillsDir)) {
171	    rmSync(globalSkillsDir, { recursive: true, force: true });
172	  }
173	  mkdirSync(globalSkillsDir, { recursive: true });
174	
175	  const copySkillsFrom = (sourceDir: string): void => {
176	    if (!existsSync(sourceDir)) return;
177	    let entries: string[];
178	    try { entries = readdirSync(sourceDir); } catch { return; }
179	    for (const entry of entries) {
180	      const srcPath = join(sourceDir, entry);
181	      try {
182	        const stat = lstatSync(srcPath);
183	        if (!stat.isDirectory()) continue;
184	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
185	      } catch (e) {
186	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
187	      }
188	    }
189	  };
190	
191	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
192	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
193	
194	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
195	  if (existsSync(wsSkillsDir)) {
196	    let entries: string[];
197	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
198	    for (const entry of entries) {
199	      if (entry === ".gitignore") continue;
200	      const srcPath = join(wsSkillsDir, entry);
201	      try {
202	        const stat = lstatSync(srcPath);
203	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
204	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
205	      } catch (e) {
206	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
207	      }
208	    }
209	  }
210	}
211	
212	function writeResult(resultPath: string, result: ExecutorResult): void {
213	  mkdirSync(dirname(resultPath), { recursive: true });
214	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
215	}
216	
217	// ── Main ──────────────────────────────────────────────────────────────────────
218	
219	async function main(): Promise<void> {
220	  // ── Read formal ABI env vars ────────────────────────────────────────────────
221	  let taskId: string;
222	  let featureId: string;
223	  let taskRepoUrl: string;
224	  let taskRepoBranch: string;
225	  let taskRepoPath: string;
226	  let briefingPath: string;
227	  let resultPath: string;
228	  let sshKeyPath: string | undefined;
229	  let githubToken: string;
230	
231	  try {
232	    taskId = requireEnv("TASK_ID");
233	    featureId = requireEnv("FEATURE_ID");
234	    taskRepoUrl = requireEnv("TASK_REPO_URL");
235	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
236	    taskRepoPath = requireEnv("TASK_REPO_PATH");
237	    briefingPath = requireEnv("BRIEFING_PATH");
238	    resultPath = requireEnv("RESULT_PATH");
239	    githubToken = process.env.GITHUB_TOKEN ?? "";
240	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
241	  } catch (e) {
242	    emit({ type: "executor_fatal", details: (e as Error).message });
243	    process.exit(1);
244	  }
245	
246	  const budgetTokensStr = process.env.BUDGET_TOKENS;
247	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
248	
249	  // Day-1 single-container extras.
250	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
251	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
252	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
253	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
254	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
255	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
256	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
257	  const mcpRagUrl = process.env.MCP_RAG_URL;
258	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
259	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
260	
261	  const runStartIso = new Date().toISOString();
262	
263	  // ── 1. Materialize implementation repo ─────────────────────────────────────
264	  try {
265	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
266	  } catch (e) {
267	    const details = `repo materialization failed: ${String(e)}`;
268	    emit({ type: "executor_fatal", task_id: taskId, details });
269	    writeResult(resultPath, {
270	      terminal_status: "failed",
271	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
272	    });
273	    process.exit(0);
274	  }
275	
276	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
277	  const missingTools = checkRequiredTools(taskRepoPath);
278	  if (missingTools.length > 0) {
279	    const details = `missing tools: ${missingTools.join(", ")}`;
280	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
281	    writeResult(resultPath, {
282	      terminal_status: "blocked",
283	      blocked_reason: "missing_tool",
284	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
285	    });
286	    process.exit(0);
287	  }
288	
289	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
290	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
291	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
292	
293	  // ── 4. Read briefing ────────────────────────────────────────────────────────
294	  let briefingContent: string;
295	  try {
296	    briefingContent = readFileSync(briefingPath, "utf-8");
297	  } catch (e) {
298	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
299	    writeResult(resultPath, {
300	      terminal_status: "failed",
301	      blocked_reason: `briefing_read_failed: ${String(e)}`,
302	    });
303	    process.exit(0);
304	  }
305	
306	  // Append hard-stop rule for missing tools.
307	  const effectiveBriefing =
308	    briefingContent +
309	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
310	
311	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
312	  const mcpArgs: string[] = [];
313	  if (mcpRagUrl || figmaToken) {
314	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
315	    if (mcpRagUrl) {
316	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
317	    }
318	    if (figmaToken) {
319	      mcpConfig.mcpServers["figma"] = {
320	        type: "stdio",
321	        command: "npx",
322	        args: ["-y", "@figma/mcp-server"],
323	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
324	      };
325	    }
326	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
327	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
328	    mcpArgs.push("--mcp-config", mcpConfigPath);
329	  }
330	
331	  // ── 6. Spawn claude — wrapped in try/finally for Layer 1 recovery ───────────
332	  const claudeEnv = {
333	    ...buildGitEnv(sshKeyPath),
334	    CLAUDE_AGENT_RUNTIME: "1",
335	    RESULT_PATH: resultPath,
336	    GITHUB_TOKEN: githubToken,
337	  };
338	
339	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
340	
341	  let spawnResult: SpawnResult | undefined;
342	  let tokenUsage: { input: number; output: number } | undefined;
343	  let logFlushed = false;
344	
345	  try {
346	    spawnResult = await new Promise<SpawnResult>((resolve) => {
347	      const stdoutChunks: string[] = [];
348	
349	      const child = spawn(
350	        "claude",
351	        [
352	          "-p", effectiveBriefing,
353	          "--max-turns", String(maxTurns),
354	          "--output-format", "stream-json",
355	          "--verbose",
356	          "--dangerously-skip-permissions",
357	          ...(implementationModel ? ["--model", implementationModel] : []),
358	          ...mcpArgs,
359	        ],
360	        { cwd: taskRepoPath, env: claudeEnv },
361	      );
362	
363	      child.stdout.setEncoding("utf-8");
364	      child.stderr.setEncoding("utf-8");
365	
366	      let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
367	      let stdoutLineBuf = "";
368	      child.stdout.on("data", (chunk: string) => {
369	        stdoutChunks.push(chunk);
370	        process.stdout.write(chunk);
371	        if (resultWatchdog === null) {
372	          stdoutLineBuf += chunk;
373	          const lines = stdoutLineBuf.split("\n");
374	          stdoutLineBuf = lines.pop() ?? "";
375	          for (const line of lines) {
376	            if (line.includes('"type":"result"')) {
377	              resultWatchdog = setTimeout(() => {
378	                if (!child.killed) child.kill("SIGTERM");
379	              }, 30_000);
380	              break;
381	            }
382	          }
383	        }
384	      });
385	
386	      child.stderr.on("data", (chunk: string) => {
387	        process.stderr.write(chunk);
388	      });
389	
390	      child.on("error", (err: Error) => {
391	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
392	        resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
393	      });
394	
395	      child.on("exit", () => {
396	        if (resultWatchdog !== null) clearTimeout(resultWatchdog);
397	        setTimeout(() => {
398	          if (!child.stdout.destroyed) child.stdout.destroy();
399	          if (!child.stderr.destroyed) child.stderr.destroy();
400	        }, 0);
401	      });
402	
403	      child.on("close", (code: number | null, signal: string | null) => {
404	        resolve({ stdout: stdoutChunks.join(""), status: code, signal });
405	      });
406	    });
407	
408	    emit({
409	      type: "claude_exit",
410	      task_id: taskId,
411	      feature_id: featureId,
412	      exit_code: spawnResult.status,
413	      signal: spawnResult.signal ?? null,
414	    });
415	
416	    // ── 7. Token audit ────────────────────────────────────────────────────────
417	    tokenUsage = spawnResult.stdout ? extractTokenUsage(spawnResult.stdout) : undefined;
418	
419	    if (tokenUsage === undefined) {
420	      emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
421	    } else {
422	      emit({
423	        type: "budget_audit",
424	        task_id: taskId,
425	        feature_id: featureId,
426	        total_tokens: tokenUsage.input + tokenUsage.output,
427	        max_tokens: budgetTokens,
428	      });
429	    }
430	
431	    // ── 8. Check for result.json written by Claude ────────────────────────────
432	    // The pr_url is sourced ONLY from Claude's result.json. The executor does not
433	    // scrape stdout for GitHub URLs, and does not synthesize an in_review result
434	    // when Claude exits cleanly without writing result.json — both paths previously
435	    // produced false-positives where unrelated PR URLs (e.g. the workspace claim PR
436	    // echoed via a Read of T<n>.yaml) were captured as the impl PR.
437	
438	    if (existsSync(resultPath)) {
439	      let raw: unknown;
440	      try {
441	        raw = JSON.parse(readFileSync(resultPath, "utf-8"));
442	      } catch {
443	        raw = null;
444	      }
445	      if (isValidResult(raw)) {
446	        let claudeResult = raw as ExecutorResult;
447	        if (tokenUsage !== undefined && !claudeResult.token_usage) {
448	          claudeResult.token_usage = tokenUsage;
449	        }
450	
451	        // Refuse terminal_status: in_review without a pr_url. Catches the case
452	        // where the agent skipped pr-create after pr-self-review and exited
453	        // anyway, so the orchestrator does not advance the task to in_review
454	        // with no impl PR (or with the workspace claim PR url misclaimed as
455	        // the impl PR — see enforce-pr-url.ts for context).
456	        const enforced = enforceInReviewRequiresPrUrl(claudeResult);
457	        if (enforced.rewritten) {
458	          emit({
459	            type: "in_review_refused_no_pr_url",
460	            task_id: taskId,
461	            feature_id: featureId,
462	          });
463	        }
464	        claudeResult = enforced.result;
465	
466	        if (
467	          budgetTokens !== undefined &&
468	          tokenUsage !== undefined &&
469	          tokenUsage.input + tokenUsage.output > budgetTokens
470	        ) {
471	          writeResult(resultPath, {
472	            terminal_status: "blocked",
473	            blocked_reason: "budget_exceeded",
474	            token_usage: tokenUsage,
475	          });
476	        } else {
477	          writeResult(resultPath, claudeResult);
478	        }
479	
480	        if (logSinkEnabled && workspaceRoot && taskBranch) {
481	          flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
482	          logFlushed = true;
483	        }
484	
485	        // Return normally — Layer 1 recovery (finally block below) will no-op
486	        // because a valid result.json now exists.
487	        return;
488	      }
489	    }
490	
491	    // ── 9. Claude did not write result.json ──────────────────────────────────
492	    // Budget-exceeded: write blocked immediately (deterministic, no recovery side-effects needed).
493	    if (
494	      budgetTokens !== undefined &&
495	      tokenUsage !== undefined &&
496	      tokenUsage.input + tokenUsage.output > budgetTokens
497	    ) {
498	      writeResult(resultPath, {
499	        terminal_status: "blocked",
500	        blocked_reason: "budget_exceeded",
501	        token_usage: tokenUsage,
502	      });
503	      if (logSinkEnabled && workspaceRoot && taskBranch) {
504	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, "blocked", sshKeyPath);
505	        logFlushed = true;
506	      }
507	      return;
508	    }
509	
510	    // No result.json produced — recovery will write one in the finally block.
511	
512	  } finally {
513	    // ── Layer 1: post-hoc recovery ────────────────────────────────────────────
514	    // Runs regardless of how the spawn ended. No-op when result.json has a
515	    // valid in_review result (Claude finished cleanly). Otherwise: commits
516	    // uncommitted work, pushes, opens a draft PR, writes handover.md, and
517	    // writes a blocked result.json.
518	    await runRecovery({
519	      spawnResult,
520	      taskId,
521	      featureId,
522	      taskRepoBranch,
523	      taskRepoPath,
524	      taskRepoUrl,
525	      githubToken,
526	      sshKeyPath,
527	      gitAuthorEmail,
528	      gitAuthorName,
529	      resultPath,
530	      tokenUsage,
531	    });
532	
533	    // Flush log after recovery (best-effort, uses result.json to determine outcome).
534	    // Skip if already flushed in the success or budget-exceeded paths above.
535	    if (!logFlushed && logSinkEnabled && workspaceRoot && taskBranch) {
536	      let outcome = "unknown";
537	      try {
538	        const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult;
539	        outcome = raw.terminal_status;
540	      } catch { /* ignore */ }
541	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult?.stdout ?? "", outcome, sshKeyPath);
542	    }
543	  }
544	}
545	
546	// ── Log flush (best-effort) ───────────────────────────────────────────────────
547	
548	function flushLog(
549	  workspaceRoot: string,
550	  featureId: string,
551	  taskId: string,
552	  taskBranch: string,
553	  runStartIso: string,
554	  gitAuthorEmail: string,
555	  gitAuthorName: string,
556	  stdout: string,
557	  outcome: string,
558	  sshKeyPath: string | undefined,
559	): void {
560	  try {
561	    const safeIso = runStartIso.replace(/[:.]/g, "-");
562	    const logFilename = `${safeIso}.jsonl`;
563	    const relLogPath = join("docs", "features", featureId, "logs", taskId, logFilename);
564	    const logPath = join(workspaceRoot, relLogPath);
565	
566	    const env = {
567	      ...process.env,
568	      GIT_AUTHOR_NAME: gitAuthorName,
569	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
570	      GIT_COMMITTER_NAME: gitAuthorName,
571	      GIT_COMMITTER_EMAIL: gitAuthorEmail,
572	      ...(sshKeyPath ? { GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new` } : {}),
573	    };
574	    const gitOpts = { env, stdio: "pipe" as const, timeout: 30_000 };
575	
576	    // Step 1: Move to the task branch tip BEFORE writing any files.
577	    // Discard local changes first — a previous failed flush may have left a dirty tree.
578	    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, gitOpts);
579	    execSync(`git -C "${workspaceRoot}" checkout -- .`, gitOpts);
580	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, gitOpts);
581	
582	    // Step 2: Write the log file (directory may not exist on this branch yet).
583	    const logsDir = join(workspaceRoot, "docs", "features", featureId, "logs", taskId);
584	    mkdirSync(logsDir, { recursive: true });
585	    appendFileSync(logPath, JSON.stringify({ at: runStartIso, by: gitAuthorEmail, type: "run_started" }) + "\n");
586	    if (stdout) {
587	      const safe = redactSecrets(stdout);
588	      appendFileSync(logPath, safe.endsWith("\n") ? safe : safe + "\n");
589	    }
590	    appendFileSync(logPath, JSON.stringify({ at: new Date().toISOString(), by: gitAuthorEmail, type: "run_ended", details: { outcome } }) + "\n");
591	
592	    // Step 3: Commit, sync with origin, then push.
593	    execSync(`git -C "${workspaceRoot}" add "${relLogPath}"`, gitOpts);
594	    execSync(`git -C "${workspaceRoot}" commit -m "chore: flush task log ${taskId}"`, gitOpts);
595	    execSync(`git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`, gitOpts);
596	    execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, gitOpts);
597	  } catch { /* best-effort */ }
598	}
599	
600	main().catch((e) => {
601	  try {
602	    console.log(JSON.stringify({ type: "fatal_error", details: String(e), at: new Date().toISOString() }));
603	  } catch { /* last resort */ }
604	  process.exit(1);
605	});

