cat > "$REPO/runtime/executors/claude/src/token-usage.ts" << 'EOF'
/**
 * Token usage extraction from claude --output-format stream-json stdout.
 */

const PRICING: Record<string, { inputPerMTok: number; outputPerMTok: number }> = {
  "claude-sonnet-4-6": { inputPerMTok: 3.0, outputPerMTok: 15.0 },
  "claude-opus-4-7": { inputPerMTok: 15.0, outputPerMTok: 75.0 },
  "claude-haiku-4-5-20251001": { inputPerMTok: 0.8, outputPerMTok: 4.0 },
};

const FALLBACK_MODEL = "claude-sonnet-4-6";

/**
 * Scan stdout lines for token usage across all formats.
 * Returns accumulated {input, output, model, cost_usd, pricingFallback}, or undefined.
 */
export function extractTokenUsage(
  stdout: string,
): { input: number; output: number; model: string; cost_usd: number; pricingFallback: boolean } | undefined {
  let input = 0;
  let output = 0;
  let lastModel: string | undefined;
  let found = false;

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;

      if (parsed.type === "assistant") {
        const msg = parsed.message as Record<string, unknown> | undefined;
        const usage = msg?.usage as Record<string, unknown> | undefined;
        if (
          typeof usage?.input_tokens === "number" &&
          typeof usage?.output_tokens === "number"
        ) {
          input += usage.input_tokens as number;
          output += usage.output_tokens as number;
          found = true;
        }
        if (typeof msg?.model === "string" && msg.model.length > 0) {
          lastModel = msg.model as string;
        }
        continue;
      }

      const usage = parsed.usage as Record<string, unknown> | undefined;
      if (
        typeof usage?.input_tokens === "number" &&
        typeof usage?.output_tokens === "number"
      ) {
        input += usage.input_tokens as number;
        output += usage.output_tokens as number;
        found = true;
      }
    } catch {
      // Not a JSON line — skip.
    }
  }

  if (!found) return undefined;

  const model = lastModel ?? FALLBACK_MODEL;
  const pricingFallback = !Object.prototype.hasOwnProperty.call(PRICING, model);
  const rates = PRICING[model] ?? PRICING[FALLBACK_MODEL]!;
  const cost_usd =
    (input / 1_000_000) * rates.inputPerMTok +
    (output / 1_000_000) * rates.outputPerMTok;

  return { input, output, model, cost_usd, pricingFallback };
}
EOF

# 2. rag-audit.ts
cat > "$REPO/runtime/executors/claude/src/rag-audit.ts" << 'EOF'
/**
 * RAG query audit — extracts tool_use/tool_result pairs from stream-json stdout.
 */

export interface RagQueryEvent {
  query: string;
  chunks_returned: number;
  top_score: number | null;
  scores: number[];
}

/**
 * Scan stream-json stdout for RAG tool_use/tool_result pairs.
 * Unmatched tool_use entries (no corresponding tool_result) are dropped silently.
 */
export function extractRagQueries(stdout: string): RagQueryEvent[] {
  const pending = new Map<string, string>(); // tool_use_id → query
  const results: RagQueryEvent[] = [];

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;
    let parsed: Record<string, unknown>;
    try {
      parsed = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    if (parsed.type === "assistant") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (
          b.type === "tool_use" &&
          b.name === "mcp__rag-server__rag_query" &&
          typeof b.id === "string"
        ) {
          const input = b.input as Record<string, unknown> | undefined;
          const query = typeof input?.query === "string" ? input.query : "";
          pending.set(b.id as string, query);
        }
      }
      continue;
    }

    if (parsed.type === "user") {
      const msg = parsed.message as Record<string, unknown> | undefined;
      const content = msg?.content;
      if (!Array.isArray(content)) continue;
      for (const block of content) {
        const b = block as Record<string, unknown>;
        if (b.type !== "tool_result" || typeof b.tool_use_id !== "string") continue;
        const query = pending.get(b.tool_use_id as string);
        if (query === undefined) continue;
        pending.delete(b.tool_use_id as string);

        const scores = parseScores(b.content);
        results.push({
          query,
          chunks_returned: scores.length,
          top_score: scores.length > 0 ? Math.max(...scores) : null,
          scores,
        });
      }
    }
  }

  return results;
}

function parseScores(content: unknown): number[] {
  if (typeof content === "string") {
    try {
      const parsed = JSON.parse(content);
      if (Array.isArray(parsed)) {
        return parsed
          .map((item: unknown) => {
            const obj = item as Record<string, unknown>;
            return typeof obj?.score === "number" ? obj.score : null;
          })
          .filter((s): s is number => s !== null);
      }
    } catch {
      // not JSON — no scores
    }
    return [];
  }

  if (Array.isArray(content)) {
    for (const block of content) {
      const b = block as Record<string, unknown>;
      if (b.type === "text" && typeof b.text === "string") {
        return parseScores(b.text);
      }
    }
  }

  return [];
}
